#!/usr/bin/env bash
# M2 Problem 1 criteria 1-2 on the running cluster (sharded storage). Self-checking.
#   1. load the historical catalog (CATALOG=<ndjson>, default: generated by tools/catalog/catalog.py with the
#      natural skew of Indonesian seismicity; convert the assistants' CSV with `catalog.py convert`)
#   2. per storage unit: node, role, active rows, bytes -> no unit holds all data; primaries on > 1 node
#   3. write load per shard and per node while the catalog is loaded, then during a one-region spike
#      (SPIKE_REGION, SPIKE_COUNT); CPU/memory per store pod (kubectl top) sampled meanwhile
#   4. the same input placed offline by the two alternatives (region ranges, time ranges) for comparison
. "$(dirname "${BASH_SOURCE[0]}")/k8s-lib.sh"
[ "$K8S_STORAGE" = sharded ] || fail "select K8S_STORAGE=sharded"
SPIKE_REGION="${SPIKE_REGION:-Sumatera Barat}" SPIKE_COUNT="${SPIKE_COUNT:-1500}"
evidence="$ROOT/docs/evidence/m2/p1-load-latest.log"
work=$(mktemp -d)
trap 'kill "${sampler:-}" 2>/dev/null || true; rm -rf "$work"; cleanup_pf' EXIT
exec > >(tee "$evidence") 2>&1
PY=$(command -v python3 || command -v python)

unit_stats() { # unit node role active_rows bytes writes(ins+upd)
  local pod
  for pod in $(kn get pods -l app=canonical-shard -o jsonpath='{.items[*].metadata.name}'); do
    store_sql "$pod" -A -t -F ' ' -c "SELECT '$pod', current_setting('argus.node'),
      CASE WHEN pg_is_in_recovery() THEN 'replica' ELSE 'primary' END,
      (SELECT count(*) FROM hazards WHERE NOT retired), pg_total_relation_size('hazards'),
      COALESCE((SELECT n_tup_ins + n_tup_upd FROM pg_stat_user_tables WHERE relname='hazards'), 0)" 2>/dev/null ||
      echo "$pod - unreachable 0 0 0"
  done | sort
}
# writes only count on primaries (a replica applies WAL; its pg_stat counters do not move)
delta() { # before after -> per unit and per node write deltas of primaries
  # join: $1 unit, $2-$6 before (node role rows bytes writes), $7-$11 after
  join "$1" "$2" | awk '{d = $11 - $6; if ($8 == "primary") {node[$7] += d; tot += d}
      printf "   %-10s %-8s %-8s rows=%-7s bytes=%-9s writes+%d\n", $1, $7, $8, $9, $10, d}
    END {for (n in node) printf "   node %-8s primary writes +%d (%.0f %%)\n", n, node[n], tot ? 100 * node[n] / tot : 0}'
}
sample_top() { while :; do kn top pods -l app=canonical-shard --no-headers 2>/dev/null | sed "s/^/   [$(date -u +%T)] /"; sleep 10; done; }
import() { # file label
  info "importing $(wc -l <"$1" | tr -d ' ') events ($2)"
  local t0=$SECONDS
  kn exec -i deploy/aggregator -c aggregator -- /usr/local/bin/aggregator import-catalog <"$1" 2>&1 | tail -n 2 | sed 's/^/   /'
  info "$2 imported in $((SECONDS - t0)) s"
}

step "1. Catalog"
if [ -z "${CATALOG:-}" ]; then
  CATALOG="$work/catalog.ndjson"
  "$PY" "$ROOT/tools/catalog/catalog.py" generate --count "${CATALOG_COUNT:-5000}" >"$CATALOG"
  warn "no CATALOG given: synthetic catalog with the natural regional skew (tools/catalog/catalog.py generate)"
fi
"$PY" "$ROOT/tools/catalog/catalog.py" spike --region "$SPIKE_REGION" --count "$SPIKE_COUNT" >"$work/spike.ndjson"

step "2. Load the catalog: write load per unit and node"
unit_stats >"$work/s0"
sample_top & sampler=$!
import "$CATALOG" catalog
unit_stats >"$work/s1"
delta "$work/s0" "$work/s1"

step "3. Spike: $SPIKE_COUNT events in one region ($SPIKE_REGION)"
import "$work/spike.ndjson" "spike"
unit_stats >"$work/s2"
kill "$sampler" 2>/dev/null || true
delta "$work/s1" "$work/s2"

step "4. Placement after loading (criterion 1)"
total=$(curl -sS --max-time 30 -H "Authorization: Bearer $AUDIT_TOKEN" "http://127.0.0.1:30083/internal/audit/checksum" | jqx -r .count)
info "active HazardEvents (Audit API): $total"
awk -v t="$total" '$3 == "primary" {n++; if ($4 >= t) all++; p[$2]++}
  END {for (k in p) printf "   node %s holds %d primary unit(s)\n", k, p[k];
       if (all) {print "   FAIL a unit holds all data"; exit 1}; if (length(p) < 2) {print "   FAIL primaries on one node"; exit 1}}' "$work/s2" ||
  fail "placement"
ok "no storage unit holds all $total events; primaries (write load) on more than one node"

step "5. The same input under the alternatives (offline, same placement count)"
"$PY" "$ROOT/tools/catalog/catalog.py" distribution "$CATALOG" "$work/spike.ndjson" --shards 3 --recent-hours 24 | sed 's/^/   /'
"$PY" "$ROOT/tools/catalog/catalog.py" distribution "$work/spike.ndjson" --shards 3 | sed 's/^/   spike only: /'
